package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.ScrapeIntervalVO;

class ScrapeIntervalValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of scrape interval of observed source")
  void test_scrape_interval_value_holder_assign_plain_value() {
    Object holder = new Object();
    ScrapeIntervalValueHolder<Object> value = new ScrapeIntervalValueHolder<>(holder);
    Assertions.assertSame(holder, value.scrapeInterval(1), "Setters must return the holder");
    Assertions.assertTrue(value.getScrapeIntervalValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getScrapeInterval().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.scrapeIntervalNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getScrapeIntervalValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getScrapeInterval().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of scrape interval of observed source")
  void test_scrape_interval_value_holder_assign_value_object() {
    Object holder = new Object();
    ScrapeIntervalValueHolder<Object> value = new ScrapeIntervalValueHolder<>(holder);
    ScrapeIntervalVO vo = ScrapeIntervalVO.from(1);
    Assertions.assertFalse(value.getScrapeIntervalValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.scrapeInterval(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getScrapeIntervalValue().orElseThrow());
    Assertions.assertSame(holder, value.scrapeInterval(Optional.empty()));
    Assertions.assertFalse(value.getScrapeIntervalValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.scrapeInterval(Optional.of(vo)));
    Assertions.assertSame(vo, value.getScrapeIntervalValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of scrape interval of observed source against the original")
  void test_scrape_interval_value_holder_read() {
    Object holder = new Object();
    ScrapeIntervalValueHolder<Object> value = new ScrapeIntervalValueHolder<>(holder);
    ScrapeIntervalVO vo = ScrapeIntervalVO.from(1);
    ScrapeIntervalVO other = ScrapeIntervalVO.from(1);
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getScrapeIntervalValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readScrapeInterval(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readScrapeInterval(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.scrapeInterval(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readScrapeInterval(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readScrapeInterval(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of scrape interval of observed source")
  void test_scrape_interval_value_holder_unset() {
    Object holder = new Object();
    ScrapeIntervalValueHolder<Object> value = new ScrapeIntervalValueHolder<>(holder);
    ScrapeIntervalVO vo = ScrapeIntervalVO.from(1);
    value.scrapeInterval(vo);
    Assertions.assertSame(holder, value.unsetScrapeIntervalIfMatches("scrapeInterval_other"));
    Assertions.assertTrue(value.getScrapeIntervalValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetScrapeIntervalIfMatches("scrapeInterval"));
    Assertions.assertFalse(value.getScrapeIntervalValue().isPresent(),
        "The field name must clear the value");
    value.scrapeInterval(vo);
    Assertions.assertSame(holder, value.unsetScrapeInterval());
    Assertions.assertFalse(value.getScrapeIntervalValue().isPresent(),
        "Unset must clear the value");
  }
}
